    audit_algo_h1: "1. What the AI does",
    audit_algo_p1: "AINA uses large language models (LLMs) to assist teachers with three tasks: answering curriculum questions in the Chat, generating teaching materials, and producing student progress reports. The AI does not make final decisions \u2014 it provides suggestions that teachers review and can override at any time.",
    audit_algo_h2: "2. How the AI generates a response",
    audit_algo_p2: "When a teacher or student sends a message, AINA sends the text to the LLM along with a system instruction that sets the context. The LLM predicts the most likely helpful response based on its training data. AINA then runs a bias check on the response before showing it to the user.",
    audit_algo_h3: "3. How the bias check works",
    audit_algo_p3: "Every AI response passes through a two-stage bias guard. First, a pattern-matching filter scans for known gender-biased or background-biased phrases. Second, a secondary LLM call evaluates the response for subtle bias. If either stage flags the response, it is replaced with a neutral fallback and the incident is logged here for admin review.",
    audit_algo_h4: "4. How learning paths are recommended",
