    privacy_hosting_note: "No personal data is transferred outside the EEA. AI inference (BSC Salamandra & Àguila via Hugging Face) is subject to EEA data processing agreements. The Processor commits to migrating to the Catalan Public Cloud as it becomes available for production educational workloads.",
