    faq_title: "Frequently Asked Questions",
    faq_q1: "What is SEBA AI (Aina)?",
    faq_a1: "SEBA AI, also known as Aina, is an artificial intelligence assistant for primary and secondary school teachers in Spain. It generates activities, assessments and teaching materials aligned with the 8 key LOMLOE competencies in Catalan, Spanish and English.",
    faq_q2: "Is it aligned with LOMLOE?",
    faq_a2: "Yes. All content generated by SEBA AI (Aina) follows the 8 key competencies of Organic Law 3/2020 (LOMLOE): linguistic communication, multilingual, mathematical, digital, personal-social-and-learning-to-learn, civic, entrepreneurial, and cultural awareness and expression.",
    faq_q3: "Is it available in Spanish?",
    faq_a3: "Yes. SEBA AI (Aina) is available in Catalan, Spanish and English. You can change the language at any time from the settings.",
    faq_q4: "Is SEBA AI free for teachers?",
    faq_a4: "SEBA AI (Aina) is free for teachers who receive an invitation from their school Director. Contact your Director or email hello@sebaenquiries.com to request access.",
    faq_q5: "How can I access SEBA AI (Aina)?",
    faq_a5: "Teachers need an invitation from the school Director. Once received, you can register at sebataeco.com or aina.forum and access all features for free.",
