    // InfantilEixos page UI
    eix_hero_badge: "Educació Infantil · 0–6 anys",
    eix_hero_title_1: "The 4 Axes of",
    eix_hero_title_2: "Development",
    eix_hero_desc: "Decree 21/2023 of the Generalitat de Catalunya structures the Educació Infantil stage around four development and learning axes, in coherence with LOMLOE (Organic Law 3/2020).",
    eix_badge_primer_cicle: "Primer cicle 0–3 · Segon cicle 3–6",
    eix_stat_eixos: "Development Axes",
    eix_stat_cicles: "Cycles",
    eix_stat_competencies: "Specific Competencies",
    eix_stat_areas: "Knowledge Areas",
    eix_intro_title: "Curricular Structure",
    eix_intro_p1: "Unlike later stages, Educació Infantil is not organised into curricular areas but into development and learning axes. Each axis integrates specific competencies, assessment criteria and curricular sabers, applied differently across the two cycles of the stage.",
    eix_intro_p2: "The four axes are not watertight compartments: the curriculum promotes a globalising approach where learning takes place in an integrated way, through play, discovery and everyday life.",
    eix_saber_area_label: "Knowledge area:",
    eix_competencies_title: "Specific Competencies",
    eix_show_sabers: "Show sabers by cycle",
    eix_hide_sabers: "Hide sabers by cycle",
    eix_primer_cicle: "Primer cicle",
    eix_segon_cicle: "Segon cicle",
    eix_enfocament_label: "Pedagogical focus",
    eix_practica_btn: "Practise",
    eix_ask_aina_btn: "Ask Aina",
    eix_principles_title: "10 Pedagogical Principles of Decree 21/2023",
    eix_principles_desc: "These principles run through all four axes and guide teaching practice in the Educació Infantil stage.",
    eix_principle_1: "Play as a learning vehicle — play is the primary way children learn, explore and make sense of the world.",
    eix_principle_2: "Emotional well-being and attachment — stable, warm relationships with adults are the foundation for all learning.",
    eix_principle_3: "Active, experiential learning — children construct knowledge through direct exploration, manipulation and discovery.",
    eix_principle_4: "Inclusive and diverse environments — every child's identity, language and family background is valued and reflected in the classroom.",
    eix_principle_5: "Holistic development — physical, emotional, social, linguistic and cognitive dimensions are developed together, not in isolation.",
    eix_principle_6: "Meaningful contexts — learning is embedded in real, relevant situations drawn from children's everyday lives.",
    eix_principle_7: "Collaborative learning — children learn with and from peers, adults and the broader community.",
    eix_principle_8: "Observation and documentation — systematic observation and pedagogical documentation guide planning and assessment.",
    eix_principle_9: "Family and community partnership — families are active partners in the educational process.",
    eix_principle_10: "Continuity and transition — coherent transitions between the two cycles and into primary school support children's development.",
    eix_principle_example_label: "Classroom example",
    eix_principle_practice_btn: "Practise this principle",
    eix_principle_dogc_btn: "View in DOGC",
    eix_principle_1_example: "Set up a free-play corner with open-ended materials (blocks, sand, fabric). Observe how children assign roles, solve problems and negotiate rules — document with photos for the pedagogical portfolio.",
    eix_principle_2_example: "Begin each session with a 5-minute 'welcome circle': children share how they feel using an emotion wheel. The teacher names and validates each emotion before moving to activity time.",
    eix_principle_3_example: "Provide a water tray with containers of different sizes. Children pour, measure and predict without instruction — the teacher asks open questions ('What happens if you use the big cup?') rather than demonstrating.",
    eix_principle_4_example: "Display family photos and greetings in every language spoken at home. During story time, choose books featuring diverse family structures, abilities and cultural backgrounds.",
    eix_principle_5_example: "A 'cooking day' activity integrates maths (measuring), language (following a recipe), science (heat changes food), social skills (taking turns) and motor development (kneading dough) in a single session.",
    eix_principle_6_example: "After a child brings in a snail from the garden, the class spends a week observing it, drawing it, counting its movements and writing a group 'snail book' — all learning stems from the child's own discovery.",
    eix_principle_7_example: "Pairs of children build a tower together with one rule: they must agree before placing each block. The teacher facilitates conflict resolution when they disagree, rather than deciding for them.",
    eix_principle_8_example: "The teacher keeps a weekly observation log per child, noting language milestones, emotional responses and motor achievements. This feeds directly into the termly progress report shared with families.",
    eix_principle_9_example: "Families are invited to 'expert mornings': a parent who is a baker, musician or gardener leads a 30-minute activity. Children connect school learning to real-world knowledge from their own community.",
    eix_principle_10_example: "In the final month of parvulari, children visit their future primary classroom, meet their new teacher and complete a 'things I can do' booklet that travels with them to Year 1.",
    eix_comparison_title: "Comparison of the Two Cycles",
    eix_comparison_desc: "Both cycles share the same four axes, but with differentiated specific competencies and sabers.",
    eix_table_aspect: "Aspect",
    eix_table_primer: "Primer cicle (0–3)",
