    audit_details: "Detalles",
    audit_algo_title: "Descripci\u00f3n del Algoritmo en Lenguaje Sencillo",
    audit_algo_subtitle: "C\u00f3mo toma decisiones la IA de AINA \u2014 para docentes, familias y reguladores",
    audit_algo_h1: "1. Qu\u00e9 hace la IA",
    audit_algo_p1: "AINA utiliza modelos de lenguaje (LLM) para ayudar a los docentes en tres tareas: responder preguntas curriculares en el Chat, generar materiales did\u00e1cticos y producir informes de progreso del alumnado. La IA no toma decisiones finales.",
    audit_algo_h2: "2. C\u00f3mo genera la IA una respuesta",
    audit_algo_p2: "Cuando un docente o estudiante env\u00eda un mensaje, AINA lo env\u00eda al LLM junto con una instrucci\u00f3n de sistema. El LLM predice la respuesta m\u00e1s \u00fatil bas\u00e1ndose en sus datos de entrenamiento. AINA ejecuta una verificaci\u00f3n de sesgo antes de mostrar la respuesta.",
    audit_algo_h3: "3. C\u00f3mo funciona la verificaci\u00f3n de sesgo",
    audit_algo_p3: "Cada respuesta pasa por un filtro de sesgo en dos etapas: detecci\u00f3n de patrones y evaluaci\u00f3n por LLM secundario. Si se detecta sesgo, la respuesta se reemplaza por una respuesta neutra y el incidente queda registrado.",
    audit_algo_h4: "4. C\u00f3mo se recomiendan las rutas de aprendizaje",
    audit_algo_p4: "AINA recopila las puntuaciones de pr\u00e1ctica en las ocho competencias LOMLOE y las env\u00eda al LLM, que genera un plan estructurado con justificaci\u00f3n escrita citando las brechas competenciales.",
    audit_algo_h5: "5. Supervisi\u00f3n humana y derecho de correcci\u00f3n",
    audit_algo_p5: "Los docentes pueden corregir cualquier nota generada por la IA en cualquier momento. Cada correcci\u00f3n queda registrada con nombre, puntuaci\u00f3n original, nueva puntuaci\u00f3n y motivo obligatorio.",
    audit_algo_h6: "6. Datos utilizados y no utilizados",
    audit_algo_p6: "AINA utiliza \u00fanicamente puntuaciones de pr\u00e1ctica e informaci\u00f3n del docente. La IA no utiliza nombres, g\u00e9nero, etnia ni datos sensibles. Todos los datos se procesan dentro del EEE.",
