    privacy_delete_desc: "Esto eliminar\u00e1 permanentemente todas tus sesiones de pr\u00e1ctica, materiales, planes de lecci\u00f3n, calendarios, evaluaciones IA, rutas de aprendizaje y tu perfil de Aina. Esta acci\u00f3n no se puede deshacer.",
