    privacy_hosting_title: "Alojamiento de Datos y Soberanía",
    privacy_hosting_desc: "Todos los datos de AINA se procesan y almacenan exclusivamente dentro del Espacio Económico Europeo (EEE). La infraestructura principal se ejecuta en la Plataforma SEBA (centros de datos del EEE). Siempre que es técnicamente posible, los datos se alojan en el Núvol Públic de Catalunya — una nube soberana catalana con tres centros de datos interconectados en Cataluña, alineada con la Estrategia IA 2030 de la Generalitat de Catalunya.",
    privacy_hosting_note: "Ningún dato personal se transfiere fuera del EEE. La inferencia de IA (BSC Salamandra y Àguila vía Hugging Face) está sujeta a acuerdos de tratamiento de datos del EEE. El Procesador se compromete a migrar a la Nube Pública Catalana cuando esté disponible para cargas de trabajo educativas en producción.",
