    // Home
    home_badge: "Currículo LOMLOE de España · 8 Competencias",
    home_hero_title: "AINA |",
    home_hero_accent: "Asistente Docente",
    home_hero_subtitle: "",
    home_hero_desc: "Practica las ocho competencias clave definidas por la ley educativa LOMLOE de España. Haz preguntas, pon a prueba tus conocimientos y obtén explicaciones alineadas con el currículo — al instante.",
    home_cta_chat: "Empezar a chatear",
    home_cta_practice: "Practicar preguntas",
    home_stats_questions: "Preguntas",
    home_stats_competencies: "Competencias",
    home_stats_year_groups: "Cursos",
    home_stats_free: "Gratis",
    home_features_title: "Todo lo que necesitas para dominar LOMLOE",
    home_feature_chat_title: "Aina — Asistente IA",
    home_feature_chat_desc: "Haz cualquier pregunta sobre el currículo LOMLOE y recibe una respuesta precisa y alineada con las competencias al instante.",
    home_feature_practice_title: "Modo Práctica",
    home_feature_practice_desc: "Evalúate con preguntas de opción múltiple alineadas con el currículo en las 8 competencias y 3 cursos.",
    home_feature_create_title: "Crear Materiales",
    home_feature_create_desc: "Genera cuestionarios, crucigramas, tarjetas, sopas de letras y más — listos para imprimir o descargar.",
    home_competencies_title: "8 Competencias LOMLOE",
    faq_title: "Preguntas frecuentes",
    faq_q1: "\u00bfQu\u00e9 es SEBA AI (Aina)?",
    faq_a1: "SEBA AI, tambi\u00e9n conocido como Aina, es un asistente de inteligencia artificial para docentes de educaci\u00f3n primaria y secundaria en Espa\u00f1a. Genera actividades, evaluaciones y materiales pedag\u00f3gicos alineados con las 8 competencias clave de la LOMLOE en catal\u00e1n, castellano e ingl\u00e9s.",
    faq_q2: "\u00bfEst\u00e1 alineado con la LOMLOE?",
    faq_a2: "S\u00ed. Todo el contenido generado por SEBA AI (Aina) sigue las 8 competencias clave de la Ley Org\u00e1nica 3/2020 (LOMLOE): comunicaci\u00f3n ling\u00fc\u00edstica, pluriling\u00fce, matem\u00e1tica, digital, personal-social-y-aprender-a-aprender, ciudadana, emprendedora y conciencia y expresi\u00f3n culturales.",
    faq_q3: "\u00bfEst\u00e1 disponible en castellano?",
    faq_a3: "S\u00ed. SEBA AI (Aina) est\u00e1 disponible en catal\u00e1n, castellano e ingl\u00e9s. Puedes cambiar el idioma en cualquier momento desde la configuraci\u00f3n.",
    faq_q4: "\u00bfEs SEBA AI gratuito para docentes?",
    faq_a4: "SEBA AI (Aina) es gratuito para los docentes que reciben una invitaci\u00f3n de su Director de centro. Contacta con tu Director o env\u00eda un correo a hello@sebaenquiries.com para solicitar acceso.",
    faq_q5: "\u00bfC\u00f3mo puedo acceder a SEBA AI (Aina)?",
    faq_a5: "Los docentes necesitan una invitaci\u00f3n del Director del centro. Una vez recibida, pod\u00e9is registraros en sebataeco.com o aina.forum y acceder a todas las funcionalidades de forma gratuita.",
