    eix_enfocament_label: "Enfoque pedagógico",
    eix_practica_btn: "Practicar",
    eix_ask_aina_btn: "Preguntar a Aina",
    eix_principles_title: "10 Principios Pedagógicos del Decreto 21/2023",
    eix_principles_desc: "Estos principios atraviesan los cuatro ejes y orientan la práctica docente en la etapa de Educació Infantil.",
    eix_principle_1: "El juego como vehículo de aprendizaje — el juego es la principal forma en que los niños aprenden, exploran y comprenden el mundo.",
    eix_principle_2: "Bienestar emocional y vínculo afectivo — las relaciones cálidas y estables con los adultos son la base de todo aprendizaje.",
    eix_principle_3: "Aprendizaje activo y experiencial — los niños construyen el conocimiento mediante la exploración directa, la manipulación y el descubrimiento.",
    eix_principle_4: "Entornos inclusivos y diversos — la identidad, la lengua y el contexto familiar de cada niño son valorados y reflejados en el aula.",
    eix_principle_5: "Desarrollo integral — las dimensiones física, emocional, social, lingüística y cognitiva se desarrollan de forma conjunta, no aislada.",
    eix_principle_6: "Contextos significativos — el aprendizaje se inscribe en situaciones reales y relevantes extraidas de la vida cotidiana de los niños.",
    eix_principle_7: "Aprendizaje colaborativo — los niños aprenden con y de sus iguales, los adultos y la comunidad.",
    eix_principle_8: "Observación y documentación — la observación sistemática y la documentación pedagógica orientan la planificación y la evaluación.",
    eix_principle_9: "Alianza con las familias y la comunidad — las familias son socios activos en el proceso educativo.",
    eix_principle_10: "Continuidad y transición — las transiciones coherentes entre los dos ciclos y hacia la educación primaria apoyan el desarrollo de los niños.",
    eix_principle_example_label: "Ejemplo en el aula",
    eix_principle_practice_btn: "Practicar este principio",
    eix_principle_dogc_btn: "Ver en el DOGC",
    eix_principle_1_example: "Instala un rincón de juego libre con materiales abiertos (bloques, arena, telas). Observa cómo los niños asignan roles, resuelven problemas y negocian normas; documenta con fotos para el portafolio pedagógico.",
    eix_principle_2_example: "Comienza cada sesión con un 'círculo de bienvenida' de 5 minutos: los niños comparten cómo se sienten usando una rueda de emociones. La docente nombra y valida cada emoción antes de pasar a la actividad.",
    eix_principle_3_example: "Ofrece una bandeja de agua con recipientes de distintos tamaños. Los niños vierten, miden y predicen sin instrucciones; la docente hace preguntas abiertas ('\u00bfQué pasa si usas el vaso grande?') en lugar de demostrar.",
    eix_principle_4_example: "Expone fotos familiares y saludos en todos los idiomas que se hablan en casa. En el momento del cuento, elige libros con estructuras familiares, capacidades y culturas diversas.",
    eix_principle_5_example: "Un 'día de cocina' integra matemáticas (medir), lengua (seguir una receta), ciencias (el calor transforma los alimentos), habilidades sociales (turnarse) y desarrollo motor (amasar) en una sola sesión.",
    eix_principle_6_example: "Después de que un niño trae un caracol del jardín, la clase pasa una semana observándolo, dibujándolo, contando sus movimientos y escribiendo un 'libro del caracol' grupal; todo el aprendizaje surge del descubrimiento del niño.",
    eix_principle_7_example: "Parejas de niños construyen una torre juntos con una regla: deben ponerse de acuerdo antes de colocar cada bloque. La docente facilita la resolución de conflictos cuando no coinciden, en lugar de decidir por ellos.",
    eix_principle_8_example: "La docente lleva un diario de observación semanal por niño, anotando hitos lingüísticos, respuestas emocionales y logros motores. Esto alimenta directamente el informe de progreso trimestral compartido con las familias.",
    eix_principle_9_example: "Las familias son invitadas a 'mañanas de expertos': un padre panadero, músico o jardinero dirige una actividad de 30 minutos. Los niños conectan el aprendizaje escolar con el conocimiento real de su propia comunidad.",
    eix_principle_10_example: "En el último mes de parvulario, los niños visitan su futura aula de primaria, conocen a su nuevo docente y completan un cuadernillo '\u00bfQué sé hacer?' que los acompaña al primer curso de primaria.",
    eix_comparison_title: "Comparativa de los Dos Ciclos",
    eix_comparison_desc: "Ambos ciclos comparten los mismos cuatro ejes, pero con competencias específicas y saberes diferenciados.",
