    audit_event_detail: "Detalls de l'Esdeveniment",
    audit_details: "Detalls",
    audit_algo_title: "Descripci\u00f3 de l'Algorisme en Llenguatge Planer",
    audit_algo_subtitle: "Com pren decisions la IA de AINA \u2014 per a docents, fam\u00edlies i reguladors",
    audit_algo_h1: "1. Qu\u00e8 fa la IA",
    audit_algo_p1: "AINA utilitza models de llenguatge (LLM) per ajudar els docents en tres tasques: respondre preguntes curriculars al Xat, generar materials did\u00e0ctics i produir informes de progr\u00e9s de l'alumnat. La IA no pren decisions finals.",
    audit_algo_h2: "2. Com genera la IA una resposta",
    audit_algo_p2: "Quan un docent o estudiant envia un missatge, AINA l'envia al LLM amb una instrucci\u00f3 de sistema. El LLM prediu la resposta m\u00e9s \u00fatil. AINA executa una verificaci\u00f3 de biaix abans de mostrar la resposta.",
    audit_algo_h3: "3. Com funciona la verificaci\u00f3 de biaix",
    audit_algo_p3: "Cada resposta passa per un filtre de biaix en dues etapes: detecci\u00f3 de patrons i avaluaci\u00f3 per LLM secundari. Si es detecta biaix, la resposta es reempla\u00e7a per una resposta neutra i l'incident queda registrat.",
    audit_algo_h4: "4. Com es recomanen els itineraris d'aprenentatge",
    audit_algo_p4: "AINA recull les puntuacions de pr\u00e0ctica en les vuit compet\u00e8ncies LOMLOE i les envia al LLM, que genera un pla estructurat amb justificaci\u00f3 escrita citant les mancances competencials.",
    audit_algo_h5: "5. Supervisi\u00f3 humana i dret de correcci\u00f3",
    audit_algo_p5: "Els docents poden corregir qualsevol nota generada per la IA en qualsevol moment. Cada correcci\u00f3 queda registrada amb nom, puntuaci\u00f3 original, nova puntuaci\u00f3 i motiu obligatori.",
    audit_algo_h6: "6. Dades utilitzades i no utilitzades",
    audit_algo_p6: "AINA utilitza \u00fanicament puntuacions de pr\u00e0ctica i informaci\u00f3 del docent. La IA no utilitza noms, g\u00e8nere, \u00e8tnia ni dades sensibles. Totes les dades es processen dins de l'EEE.",
