    privacy_hosting_note: "Cap dada personal no es transfereix fora de l'EEE. La inferença d'IA (BSC Salamandra i Àguila via Hugging Face) està subjecta a acords de tractament de dades de l'EEE. El Processador es compromet a migrar al Núvol Públic de Catalunya quan estigui disponible per a càrregues de treball educatives en producció.",
