    home_feature_practice_desc: "Avalua't amb preguntes d'opció múltiple alineades amb el currículum en les 8 competències i 3 cursos.",
    home_feature_create_title: "Crear Materials",
    home_feature_create_desc: "Genera qüestionaris, mots encreuats, targetes, sopes de lletres i més — a punt per imprimir o descarregar.",
    home_competencies_title: "8 Competències LOMLOE",
    faq_title: "Preguntes freqüents",
    faq_q1: "Qu\u00e8 \u00e9s SEBA AI (Aina)?",
    faq_a1: "SEBA AI, tamb\u00e9 conegut com Aina, \u00e9s un assistent d'intel\u00b7lig\u00e8ncia artificial per a docents d'educaci\u00f3 prim\u00e0ria i secund\u00e0ria a Espanya. Genera activitats, avaluacions i materials pedag\u00f2gics alineats amb les 8 compet\u00e8ncies clau de la LOMLOE en catal\u00e0, castell\u00e0 i angl\u00e8s.",
    faq_q2: "Est\u00e0 alineat amb la LOMLOE?",
    faq_a2: "S\u00ed. Tot el contingut generat per SEBA AI (Aina) segueix les 8 compet\u00e8ncies clau de la Llei Org\u00e0nica 3/2020 (LOMLOE): comunicaci\u00f3 ling\u00fcistica, pluriling\u00fce, matem\u00e0tica, digital, personal-social-i-aprendre-a-aprendre, ciutadana, emprenedora i consci\u00e8ncia i expressi\u00f3 culturals.",
    faq_q3: "Est\u00e0 disponible en castell\u00e0?",
    faq_a3: "S\u00ed. SEBA AI (Aina) est\u00e0 disponible en catal\u00e0, castell\u00e0 i angl\u00e8s. Podeu canviar l'idioma en qualsevol moment des de la configuraci\u00f3.",
    faq_q4: "SEBA AI \u00e9s gratu\u00eft per als docents?",
    faq_a4: "SEBA AI (Aina) \u00e9s gratu\u00eft per als docents que reben una invitaci\u00f3 del Director del centre. Contacteu amb el vostre Director o envieu un correu a hello@sebaenquiries.com per sol\u00b7licitar acc\u00e9s.",
    faq_q5: "Com puc accedir a SEBA AI (Aina)?",
    faq_a5: "Els docents necessiten una invitaci\u00f3 del Director del centre. Un cop rebuda, podeu registrar-vos a sebataeco.com o aina.forum i accedir a totes les funcionalitats gratu\u00eftament.",
