    ai_models_badge_stt: "Veu a text",
    ai_models_salamandra_desc: "Salamandra 2 és una família de models de llenguatge de gran escala de codi obert desenvolupats pel Barcelona Supercomputing Center (BSC) com a part del Projecte Aina. Entrenat en un corpus multilingüe amb gran cobertura del català, l'espanyol i l'anglès, és el model de llenguatge principal que impulsa l'assistent conversacional de SEBA (Aina), la planificació de lliçons i la generació de contingut alineat amb el currículum.",
