    ai_models_aguila_desc: "Àguila (Agile General-purpose Language model for Iberian LAnguages) és un model de llenguatge bilingüe de codi obert desenvolupat pel Barcelona Supercomputing Center (BSC). Està optimitzat per a l'espanyol i el català i actua com a model complementari a SEBA per a tasques que requereixen comprensió d'alta qualitat de les llengües ibèriques, incloent comprensió lectora, resum i generació de retroalimentació per a estudiants.",
