    // InfantilEixos page UI
    eix_hero_badge: "Educació Infantil · 0–6 anys",
    eix_hero_title_1: "Els 4 Eixos de",
    eix_hero_title_2: "Desenvolupament",
    eix_hero_desc: "El Decret 21/2023 de la Generalitat de Catalunya estructura l'etapa d'Educació Infantil al voltant de quatre eixos de desenvolupament i aprenentatge, en coherència amb la LOMLOE (Llei Orgànica 3/2020).",
    eix_badge_primer_cicle: "Primer cicle 0–3 · Segon cicle 3–6",
    eix_stat_eixos: "Eixos de Desenvolupament",
    eix_stat_cicles: "Cicles",
    eix_stat_competencies: "Competències específiques",
    eix_stat_areas: "Àrees de sabers",
    eix_intro_title: "Estructura curricular",
    eix_intro_p1: "A diferència de les etapes posteriors, l'Educació Infantil no s'organitza en àrees curriculars sinó en eixos de desenvolupament i aprenentatge. Cada eix integra competències específiques, criteris d'avaluació i sabers curriculars, i s'aplica de manera diferenciada als dos cicles de l'etapa.",
    eix_intro_p2: "Els quatre eixos no són compartiments estancs: el currículum promou un enfocament globalitzador on els aprenentatges es produeixen de manera integrada, a través del joc, la descoberta i la vida quotidiana.",
    eix_saber_area_label: "Àrea de sabers:",
    eix_competencies_title: "Competències específiques",
    eix_show_sabers: "Mostra els sabers per cicle",
    eix_hide_sabers: "Amaga els sabers per cicle",
    eix_primer_cicle: "Primer cicle",
    eix_segon_cicle: "Segon cicle",
    eix_enfocament_label: "Enfocament pedagògic",
    eix_practica_btn: "Practica",
    eix_ask_aina_btn: "Pregunta a Aina",
    eix_principles_title: "10 Principis pedagògics del Decret 21/2023",
    eix_principles_desc: "Aquests principis travessen tots quatre eixos i orienten la pràctica docent a l'etapa d'Educació Infantil.",
    eix_principle_1: "El joc com a vehicle d'aprenentatge — el joc és la manera principal com els infants aprenen, exploren i comprenen el món.",
    eix_principle_2: "Benestar emocional i vincle afectiu — les relacions càlides i estables amb els adults són la base de tot aprenentatge.",
    eix_principle_3: "Aprenentatge actiu i experimental — els infants construeixen el coneixement mitjançant l'exploració directa, la manipulació i el descobriment.",
    eix_principle_4: "Entorns inclusius i diversos — la identitat, la llengua i el context familiar de cada infant són valorats i reflectits a l'aula.",
    eix_principle_5: "Desenvolupament integral — les dimensions física, emocional, social, lingüística i cognitiva es desenvolupen de manera conjunta, no aïllada.",
    eix_principle_6: "Contextos significatius — l'aprenentatge s'inscriu en situacions reals i rellevants extretes de la vida quotidiana dels infants.",
    eix_principle_7: "Aprenentatge col·laboratiu — els infants aprenen amb i dels seus iguals, els adults i la comunitat.",
    eix_principle_8: "Observació i documentació — l'observació sistemàtica i la documentació pedagògica orienten la planificació i l'avaluació.",
    eix_principle_9: "Aliança amb les famílies i la comunitat — les famílies són socis actius en el procés educatiu.",
    eix_principle_10: "Continuitat i transició — les transicions coherents entre els dos cicles i cap a l'educació primària donen suport al desenvolupament dels infants.",
    eix_principle_example_label: "Exemple a l'aula",
    eix_principle_practice_btn: "Practicar aquest principi",
    eix_principle_dogc_btn: "Veure al DOGC",
    eix_principle_1_example: "Prepara un racó de joc lliure amb materials oberts (blocs, sorra, teles). Observa com els infants assignen rols, resolen problemes i negocien normes; documenta amb fotos per al portafolis pedagògic.",
    eix_principle_2_example: "Comença cada sessió amb un 'cercle de benvinguda' de 5 minuts: els infants comparteixen com se senten amb una roda d'emocions. La docent anomena i valida cada emoció abans de passar a l'activitat.",
    eix_principle_3_example: "Ofereix una safata d'aigua amb recipients de mides diverses. Els infants aboquen, mesuren i prediuen sense instruccions; la docent fa preguntes obertes ('Què passa si fas servir el got gran?') en lloc de demostrar.",
    eix_principle_4_example: "Exposa fotos familiars i salutacions en totes les llengues que es parlen a casa. A l'hora del conte, tria llibres amb estructures familiars, capacitats i orígens culturals diversos.",
    eix_principle_5_example: "Un 'dia de cuina' integra matemàtiques (mesurar), llengua (seguir una recepta), ciències (la calor transforma els aliments), habilitats socials (tornar-se) i desenvolupament motor (pastar) en una sola sessió.",
    eix_principle_6_example: "Després que un infant porta un caragol del jardí, la classe passa una setmana observant-lo, dibuixant-lo, comptant els seus moviments i escrivint un 'llibre del caragol' col·lectiu; tot l'aprenentatge sorgeix del descobriment de l'infant.",
    eix_principle_7_example: "Parelles d'infants construeixen una torre junts amb una regla: han de posar-se d'acord abans de col·locar cada bloc. La docent facilita la resolució de conflictes quan no coincideixen, en lloc de decidir per ells.",
    eix_principle_8_example: "La docent porta un diari d'observació setmanal per infant, anotant fites lingüístiques, respostes emocionals i assoliments motors. Això alimenta directament l'informe de progrés trimestral compartit amb les famílies.",
    eix_principle_9_example: "Les famílies són convidades a 'matins d'experts': un pare flequera, músic o jardiner dirigeix una activitat de 30 minuts. Els infants connecten l'aprenentatge escolar amb el coneixement real de la seva pròpia comunitat.",
    eix_principle_10_example: "A l'últim mes de parvulari, els infants visiten la seva futura aula de primària, coneixen el seu nou docent i completen un quadernet 'Què sé fer?' que els acompanya al primer curs de primària.",
    eix_comparison_title: "Comparativa dels dos cicles",
    eix_comparison_desc: "Tots dos cicles comparteixen els mateixos quatre eixos, però amb competències específiques i sabers diferenciats.",
    eix_table_aspect: "Aspecte",
    eix_table_primer: "Primer cicle (0–3)",
    eix_table_segon: "Segon cicle (3–6)",
    eix_row_denominacio: "Denominació",
